document.addEventListener("DOMContentLoaded",function(){const t=document.querySelectorAll(".tab-button"),e=document.querySelectorAll(".skill-card");t.forEach(o=>{o.addEventListener("click",function(){t.forEach(t=>t.classList.remove("active")),this.classList.add("active");const o=this.getAttribute("data-filter");e.forEach(t=>{"all"===o||t.getAttribute("data-filter")===o?(t.style.display="block",t.style.opacity="0",setTimeout(()=>{t.style.transition="opacity 0.3s ease",t.style.opacity="1"},10)):t.style.display="none"})})});const o=document.querySelector(".btn-add-skill");o&&o.addEventListener("click",function(){showToast("Fonctionnalité à venir : Ajout de compétence","info")});document.querySelectorAll(".action-btn").forEach(t=>{t.addEventListener("click",function(t){t.preventDefault();const e=this.getAttribute("title");"Supprimer"===e?confirm("Êtes-vous sûr de vouloir supprimer cette compétence ?")&&this.closest(".skill-card").remove():"Éditer"===e?alert("Functionality to edit this skill will be implemented soon!"):"Voir"===e&&alert("Functionality to view skill details will be implemented soon!")})});const i=document.querySelector(".search-input");i&&i.addEventListener("input",function(t){const o=t.target.value.toLowerCase();e.forEach(t=>{const e=t.querySelector(".skill-title").textContent.toLowerCase(),i=t.querySelector(".skill-description").textContent.toLowerCase();e.includes(o)||i.includes(o)?t.style.display="block":t.style.display="none"})})});